ASSERTIONS = [
    'Execute only the exact named Original tests with unchanged setup, data setup, inheritance, helpers, mocks, teardown and assertions',
    'Keep Source actor declarations, explicit field writes, forced authentication, proxy environment and permission bypasses attached to each workflow',
    'Bind only matching endpoint dispatch source; factory/request helpers and mocked credential failures are not TCP, production permissions, broker or full-endpoint acceptance',
    'Reuse the actual successful named full3362 log blocks without new Source execution; static helper sites are not runtime request or branch counts',
    'Preserve all existing operation IDs, declared null methods, unrelated role slices and fully-verified=false',
]


def digest(raw):
    return hashlib.sha256(raw).hexdigest()


def source_segment(text, node):
    return ast.get_source_segment(text, node)


def checked_sources(root):
    documents = {}
    for reference in ORIGINAL_FILES + AUTHORITIES:
        path = root / reference['path']
        assert digest(path.read_bytes()) == reference['sha256'], 'exact pinned Source authority ' + reference['path']
        if reference in ORIGINAL_FILES:
            text = path.read_text()
            documents[reference['original_path']] = (text, ast.parse(text))
    return documents


def class_graph(documents):
    classes = {(path, node.name): node for path, (_, tree) in documents.items()
               for node in tree.body if isinstance(node, ast.ClassDef)}

    def lineage(path, name, trail=None):
        trail = set() if trail is None else set(trail)
        key = (path, name)
        assert key not in trail, 'bounded Original fixture inheritance'
        trail.add(key)
        cls = classes[key]
        parents = []
        for base in cls.bases:
            if not isinstance(base, ast.Name):
                continue
            same = (path, base.id)
            candidates = [candidate for candidate in classes if candidate[1] == base.id]
            target = same if same in classes else candidates[0] if len(candidates) == 1 else None
            if target is not None:
                parents.extend(lineage(*target, trail))
        return list(dict.fromkeys(parents + [key]))

    return classes, lineage


def method_definitions(classes, lineage, path, name):
    methods = {}
    chain = lineage(path, name)
    for owner in chain:
        for node in classes[owner].body:
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                methods[node.name] = (owner, node)
    for offset, owner in enumerate(chain):
        for node in classes[owner].body:
            if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                continue
            for prior in reversed(chain[:offset]):
                target = next((candidate for candidate in classes[prior].body
                               if isinstance(candidate, (ast.FunctionDef, ast.AsyncFunctionDef)) and candidate.name == node.name), None)
                if target is not None:
                    methods['super:' + owner[0] + ':' + owner[1] + ':' + node.name] = (prior, target)
                    break
    return methods


def reachable_methods(methods, first):
    pending = [first]
    found = {}
    while pending:
        name = pending.pop()
        if name in found or name not in methods:
            continue
        owner, method = methods[name]
        found[name] = (owner, method)
        for node in ast.walk(method):
            if (isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)
                    and isinstance(node.func.value, ast.Name) and node.func.value.id == 'self'):
                pending.append(node.func.attr)
            elif (isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)
                  and isinstance(node.func.value, ast.Call) and ast.unparse(node.func.value.func) == 'super'):
                pending.append('super:' + owner[0] + ':' + owner[1] + ':' + node.func.attr)
    return found


def definition(documents, owner, node):
    text = documents[owner[0]][0]
    return {'source_file': owner[0], 'class': owner[1], 'line': node.lineno,
            'source_ast_sha256': ast_fingerprint(node), 'source': source_segment(text, node)}


def role_context(root, documents, class_chain, classes, reached, test, levels=None, default=None):
    if levels is None:
        levels, default = user_defaults(root)
    blocks = [(owner, node) for owner in class_chain for node in classes[owner].body
              if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
              and node.name in ['setUp', 'setUpTestData']]
    blocks.extend(reached.values())
    creations, authentication, permission_mocks, explicit_writes = [], [], [], []
    seen = set()
    for owner, method in blocks:
        text = documents[owner[0]][0]
        for node in ast.walk(method):
            location = (owner[0], getattr(node, 'lineno', None), getattr(node, 'col_offset', None), type(node).__name__)
            if location in seen:
                continue
            seen.add(location)
            if isinstance(node, ast.Assign):
                targets = [ast.unparse(value) for value in node.targets]
                if any(value.endswith(('.user_level', '.is_staff', '.is_superuser')) for value in targets):
                    explicit_writes.append({'source_file': owner[0], 'line': node.lineno,
                                            'source': source_segment(text, node), 'targets': targets})
            if not isinstance(node, ast.Call):
                continue
            expression = ast.unparse(node.func)
            keywords = {keyword.arg: keyword.value for keyword in node.keywords}
            if expression.endswith(('.create_user', '.create_superuser', 'User.objects.create')) or expression in ['MagicMock', 'Mock'] and 'user_level' in keywords:
                level = keywords.get('user_level')
                if level is None:
                    effective = 10 if expression.endswith('.create_superuser') else default
                    authority = 'pinned CustomUserManager default10' if expression.endswith('.create_superuser') else 'pinned User.user_level omitted default'
                elif isinstance(level, ast.Constant) and type(level.value) is int:
                    effective, authority = level.value, ast.unparse(level)
                elif isinstance(level, ast.Attribute) and level.attr in levels:
                    effective, authority = levels[level.attr], ast.unparse(level)
                else:
                    effective, authority = None, 'explicit unresolved expression ' + ast.unparse(level)
                creations.append({'source_file': owner[0], 'line': node.lineno,
                                  'source': source_segment(text, node), 'declared_user_level': effective,
                                  'level_authority': authority,
                                  'synthetic_mock_not_DB_user': expression in ['MagicMock', 'Mock']})
            if expression.endswith('force_authenticate') or expression == 'force_authenticate':
                authentication.append({'source_file': owner[0], 'line': node.lineno,
                                       'source': source_segment(text, node), 'credential_backend_bypassed': True})
            if expression.endswith('patch.object') and len(node.args) >= 2 and isinstance(node.args[1], ast.Constant) and node.args[1].value == 'get_permissions':
                permission_mocks.append({'source_file': owner[0], 'line': node.lineno,
                                         'source': source_segment(text, node), 'real_permission_coverage': False})
    return {'Original_User_level_enum': levels, 'omitted_User_level_default': default,
            'fixture_user_declarations': creations, 'explicit_user_field_writes': explicit_writes,
            'forced_authentication_expressions': authentication, 'permission_bypass_expressions': permission_mocks,
            'role_resolution_scope': 'Exact fixture source and chronology, not inferred complete role coverage; created actors are not automatically every request actor',
            'test_method': test.name, 'complete_role_matrix': False}


def fixture_definition(documents, classes, class_chain):
    fixture = []
    for owner in class_chain:
        cls = classes[owner]
        text = documents[owner[0]][0]
        fixture.append({'source_file': owner[0], 'class': owner[1], 'class_ast_sha256': ast_fingerprint(cls),
                        'class_decorators': [source_segment(text, decorator) for decorator in cls.decorator_list],
                        'fixture_methods': {node.name: definition(documents, owner, node) for node in cls.body
                                            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
                                            and node.name in ['setUp', 'setUpTestData', 'tearDown']}})
    return fixture


def dispatch_scope(pattern):
    if pattern == 'api/accounts/auth/proxy-login/':
        return {'transport': 'Original APIClient with controlled reverse-proxy headers/environment; source-level JWT response assertions only',
                'observed_methods': ['POST'], 'role_label': 'Original_reverse_proxy_header_fixture'}
    if pattern.startswith('api/plugins/'):
        return {'transport': 'Original APIClient or direct APIRequestFactory as_view with explicit get_permissions bypass/installer/network/DB-close mocks where present',
                'observed_methods': ['DELETE'] if pattern.endswith('/delete/') else ['POST'],
                'role_label': 'Original_plugin_lifecycle_fixture_with_scoped_permission_mocks'}
    if pattern.startswith(('api/catchup/', 'api/proxy/hls/')):
        return {'transport': 'Original APIClient dispatch with forced fixture actors and mocked network/Redis/session service effects',
                'observed_methods': ['DELETE'] if '<str:session_id>/' in pattern and not pattern.endswith('/position/') or pattern.startswith('api/proxy/hls/') else ['POST'],
                'role_label': 'Original_forced_session_actor_fixture'}
    if pattern in ['player_api.php', 'panel_api.php', 'get.php', 'xmltv.php']:
        return {'transport': 'Original RequestFactory -> exact top-level view parameter; credential/network rejection responses mocked, no XC auth or TCP proof',
                'observed_methods': ['GET'], 'role_label': 'Original_mocked_XC_auth_error_fixture'}
    if pattern.startswith('proxy/hls/'):
        return {'transport': 'Original RequestFactory direct actual HLS view with mocked Proxy/session/buffer, not media network',
                'observed_methods': ['GET'], 'role_label': 'Original_mocked_HLS_capability_fixture'}
    return {'transport': 'Original APIRequestFactory direct actual handler with exact forced/synthetic actor and Redis/network/build/stop mocks',
            'observed_methods': ['POST'] if pattern in ['proxy/catchup/programs/', 'proxy/catchup/stop_client/'] else ['GET'],
            'role_label': 'Original_forced_or_synthetic_proxy_fixture'}


REQUEST_VERBS = {'get', 'post', 'delete', 'put', 'patch', 'head', 'options'}
RECEIVERS = {'self.api', 'self.client', 'self.factory', 'self._factory', 'authed'}
DISPATCH = {
    'api/plugins/plugins/<str:key>/enabled/': 'PluginEnabledAPIView.as_view()',
    'api/plugins/plugins/<str:key>/delete/': 'PluginDeleteAPIView.as_view()',
    'api/plugins/repos/install/': 'PluginInstallFromRepoAPIView.as_view()',
    'proxy/stats/': 'stats_views.combined_stats',
    'proxy/catchup/stats/': 'stats_views.timeshift_stats',
    'proxy/catchup/programs/': 'stats_views.catchup_programmes',
    'proxy/catchup/stop_client/': 'stats_views.stop_timeshift_session',
    'proxy/hls/<str:token>/index.m3u8': 'hls_views.hls_playlist',
    'proxy/hls/<str:token>/<int:seq>.ts': 'hls_views.hls_segment',
    'proxy/catchup/<uuid:channel_id>': 'views.catchup_proxy',
    'player_api.php': 'xc_player_api', 'panel_api.php': 'xc_panel_api',
    'get.php': 'xc_get', 'xmltv.php': 'xc_xmltv',
}


def fixture_environment(documents, chain, classes):
    environment = {}
    for filename, _ in chain:
        tree = documents[filename][1]
        for node in tree.body:
            if isinstance(node, ast.Assign):
                for target in node.targets:
                    if isinstance(target, ast.Name) and isinstance(node.value, (ast.Constant, ast.JoinedStr, ast.BinOp)):
                        environment[target.id] = node.value
    for owner in chain:
        for method in classes[owner].body:
            if not isinstance(method, ast.FunctionDef) or method.name not in ['setUp', 'setUpTestData']:
                continue
            for node in ast.walk(method):
                if isinstance(node, ast.Assign):
                    for target in node.targets:
                        key = ast.unparse(target)
                        if key.startswith('cls.'):
                            key = 'self.' + key[4:]
                        environment[key] = node.value
    return environment


def url_expression(node, environment, methods, depth=0, resolving=None):
    assert depth <= 12, 'bounded literal fixture URL expression'
    resolving = set() if resolving is None else set(resolving)
    key = ast.unparse(node)
    if key in environment and key not in resolving:
        resolving.add(key)
        return url_expression(environment[key], environment, methods, depth + 1, resolving)
    if isinstance(node, ast.Constant) and isinstance(node.value, (str, int)):
        return str(node.value)
    if isinstance(node, ast.JoinedStr):
        parts = []
        for item in node.values:
            if isinstance(item, ast.Constant):
                parts.append(str(item.value))
            elif isinstance(item, ast.FormattedValue):
                parts.append(url_expression(item.value, environment, methods, depth + 1, resolving))
            else:
                raise ValueError('UnsupportedFixtureFString')
        return ''.join(parts)
    if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):
        return url_expression(node.left, environment, methods, depth + 1, resolving) + url_expression(node.right, environment, methods, depth + 1, resolving)
    if isinstance(node, ast.Call) and ast.unparse(node.func) == 'str' and len(node.args) == 1 and not node.keywords:
        return url_expression(node.args[0], environment, methods, depth + 1, resolving)
    if isinstance(node, ast.Call) and ast.unparse(node.func) == 'uuid.uuid4' and not node.args and not node.keywords:
        return '{UUID4:uuid.uuid4()}'
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and ast.unparse(node.func.value) == 'self' and node.func.attr in methods:
        owner, helper = methods[node.func.attr]
        returns = [item.value for item in helper.body if isinstance(item, ast.Return)]
        if len(returns) == 1:
            bound = helper_environment(helper, node, environment)
            return url_expression(returns[0], bound, methods, depth + 1, resolving)
    if (isinstance(node, ast.Subscript) and isinstance(node.slice, ast.Constant) and node.slice.value == 'session_id'
            and isinstance(node.value, ast.Call) and isinstance(node.value.func, ast.Attribute)
            and node.value.func.attr == 'json' and not node.value.args and not node.value.keywords):
        # This is a Source response-derived opaque ID template, not a concrete
        # token or invented recorded request URI. The producer expression stays
        # attached to the original workflow and is never evaluated here.
        return '{' + key + '}'
    if isinstance(node, (ast.Name, ast.Attribute)):
        return '{' + key + '}'
    raise ValueError('UnqualifiedFixtureURLExpression: ' + key)


def matched_route(registry, template, observed_method):
    supplied = template.split('?', 1)[0].lstrip('/')
    supplied = supplied.replace('{UUID4:uuid.uuid4()}', '00000000-0000-0000-0000-000000000001')
    for route in registry['runtime_routes']:
        pattern = route['pattern_exact'].replace('/^', '/')
        # No guessed URL aliases, trailing slash normalization or format suffix.
        pattern = re.sub(r'<int:[^>]+>', r'[0-9]+', pattern)
        pattern = re.sub(r'<str:[^>]+>', r'[^/]+', pattern)
        pattern = re.sub(r'<uuid:[^>]+>', r'[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}', pattern)
        try:
            matched = re.fullmatch(pattern, supplied)
        except re.error:
            continue
        if not matched:
            continue
        for operation in route['operations']:
            if operation['method'] in [observed_method, None]:
                return route, operation
        raise ValueError('ObservedMethodNotRepresentedByDeclaration')
    raise ValueError('NoExactExistingRouteForFixture: ' + template)


def helper_environment(method, call, environment):
    import copy
    names = [node.arg for node in method.args.args if node.arg not in ['self', 'cls']]
    values = dict(zip(names[-len(method.args.defaults):], method.args.defaults)) if method.args.defaults else {}
    values.update(zip(names, call.args))
    values.update((node.arg, node.value) for node in call.keywords if node.arg is not None)
    result = dict(environment)
    for name, node in values.items():
        # Resolve only direct caller aliases once; never evaluate expressions.
        key = ast.unparse(node)
        result[name] = copy.deepcopy(environment.get(key, node))
    return result


def endpoint_sites(documents, methods, test, environment, selected, registry, depth=0, trail=None, dispatch_context=None):
    assert depth <= 12, 'bounded fixture helper trace'
    trail = [] if trail is None else list(trail)
    owner, method = methods[test]
    assert test not in trail, 'fixture helper recursion is unsupported'
    trail.append(test)
    text = documents[owner[0]][0]
    nodes = sorted((node for node in ast.walk(method) if isinstance(node, ast.Call)), key=lambda node: (node.lineno, node.col_offset))
    assignments = sorted((node for node in ast.walk(method) if isinstance(node, ast.Assign)), key=lambda node: node.lineno)
    result = []
    dispatch_context = [] if dispatch_context is None else list(dispatch_context)
    for call in nodes:
        current = dict(environment)
        for assignment in assignments:
            if assignment.lineno >= call.lineno:
                continue
            for target in assignment.targets:
                current[ast.unparse(target)] = assignment.value
        if isinstance(call.func, ast.Attribute) and ast.unparse(call.func.value) == 'self' and call.func.attr in methods and call.func.attr != test:
            _, helper = methods[call.func.attr]
            result.extend(endpoint_sites(documents, methods, call.func.attr, helper_environment(helper, call, current), selected, registry, depth + 1, trail, dispatch_context + [(owner, nodes, current)]))
        if (isinstance(call.func, ast.Attribute) and isinstance(call.func.value, ast.Call)
                and ast.unparse(call.func.value.func) == 'super'):
            super_key = 'super:' + owner[0] + ':' + owner[1] + ':' + call.func.attr
            if super_key in methods:
                _, helper = methods[super_key]
                result.extend(endpoint_sites(documents, methods, super_key, helper_environment(helper, call, current), selected, registry,
                                             depth + 1, trail, dispatch_context + [(owner, nodes, current)]))
        if not isinstance(call.func, ast.Attribute) or call.func.attr not in REQUEST_VERBS or ast.unparse(call.func.value) not in RECEIVERS or not call.args:
            continue
        template = url_expression(call.args[0], current, methods)
        try:
            route, operation = matched_route(registry, template, call.func.attr.upper())
        except ValueError:
            # An unresolved template is not a route claim. Known selected cases
            # must still produce their exact qualified operation below.
            continue
        identifier = operation['contract_id']
        if identifier not in selected:
            continue
        receiver = ast.unparse(call.func.value)
        factory = receiver in ['self.factory', 'self._factory']
        dispatch = []
        if factory:
            expected = DISPATCH[route['pattern_exact']]
            assigned_request_names = {ast.unparse(target) for assignment in assignments
                                      if assignment.value is call for target in assignment.targets}
            for dispatch_owner, candidates, dispatch_environment in dispatch_context + [(owner, nodes, current)]:
                dispatch_text = documents[dispatch_owner[0]][0]
                for candidate in candidates:
                    symbol = ast.unparse(candidate.func)
                    if symbol == 'view' and 'view' in dispatch_environment:
                        symbol = ast.unparse(dispatch_environment['view'])
                    if symbol != expected or not candidate.args:
                        continue
                    supplied_request = candidate.args[0]
                    same_local_request = dispatch_owner == owner and ast.unparse(supplied_request) in assigned_request_names
                    returned_helper_request = (isinstance(supplied_request, ast.Call)
                                               and isinstance(supplied_request.func, ast.Attribute)
                                               and ast.unparse(supplied_request.func.value) == 'self'
                                               and supplied_request.func.attr == test)
                    if same_local_request or returned_helper_request:
                        dispatch.append({'source_file': dispatch_owner[0], 'source_class': dispatch_owner[1],
                                         'line': candidate.lineno, 'source': source_segment(dispatch_text, candidate),
                                         'source_ast_sha256': ast_fingerprint(candidate)})
            assert dispatch, 'factory request requires matching top-level endpoint dispatch, not serializer/helper association'
        result.append({'contract_id': identifier, 'source_file': owner[0], 'source_class': owner[1], 'helper_path': trail,
                       'line': call.lineno, 'source': source_segment(text, call), 'source_ast_sha256': ast_fingerprint(call),
                       'observed_method': call.func.attr.upper(), 'fixture_URI_or_template': template,
                       'unresolved_template_symbols': re.findall(r'\{([^}]+)\}', template),
                       'matching_endpoint_dispatch': dispatch,
                       'transport': 'direct framework factory endpoint only' if factory else 'Original test-client dispatch only',
                       'static_site_not_runtime_request_or_branch_count': True})
    return result


def derive(root, registry):
    root = Path(root)
    documents = checked_sources(root)
    classes, lineage = class_graph(documents)
    index = {operation['contract_id']: (route, operation) for route in registry['runtime_routes'] for operation in route['operations']}
    fixtures, cases = {}, {}
    levels, default = user_defaults(root)
    for identifier, coordinate in TEST_COORDINATES.items():
        owner = (coordinate['source_file'], coordinate['class'])
        cls = classes[owner]
        test = next(node for node in cls.body if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == coordinate['method'])
        assert test.lineno == coordinate['line'], 'exact named Source coordinates'
        methods = method_definitions(classes, lineage, *owner)
        reached = reachable_methods(methods, test.name)
        text = documents[owner[0]][0]
        assertions = [source_segment(text, node) for node in ast.walk(test)
                      if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr.startswith('assert')]
        helper_assertions = []
        for helper_name, (helper_owner, helper) in reached.items():
            if helper_name == test.name:
                continue
            helper_text = documents[helper_owner[0]][0]
            helper_assertions.extend({'helper': helper_name, 'source_file': helper_owner[0],
                                      'line': node.lineno, 'expression': source_segment(helper_text, node)}
                                     for node in ast.walk(helper) if isinstance(node, ast.Call)
                                     and isinstance(node.func, ast.Attribute) and node.func.attr.startswith('assert'))
        assert assertions or helper_assertions, 'no assertion-free workflow assignment'
        chain = lineage(*owner)
        fixture_id = owner[0] + ':' + owner[1]
        if fixture_id not in fixtures:
            fixtures[fixture_id] = fixture_definition(documents, classes, chain)
        helper_definitions = {name: definition(documents, source_owner, node) for name, (source_owner, node) in reached.items() if name != test.name}
        selected = {operation for operation, tests in EXPECTED_TESTS.items() if identifier in tests}
        sites = endpoint_sites(documents, methods, test.name, fixture_environment(documents, chain, classes), selected, registry)
        assert {site['contract_id'] for site in sites} == selected, 'exact case endpoint dispatch: ' + identifier

        cases[identifier] = {'test_id': identifier, 'source_path': owner[0], 'class': owner[1], 'method': test.name,
                             'fixture_id': fixture_id, 'source_ast_sha256': ast_fingerprint(test),
                             'source_method': source_segment(text, test), 'assertion_expressions': assertions,
                             'helper_assertion_expressions': helper_assertions,
                             'class_and_inherited_setup': fixtures[fixture_id], 'helper_definitions': helper_definitions,
                             'decorators': [source_segment(text, node) for node in test.decorator_list],
                             'role_context': role_context(root, documents, chain, classes, reached, test, levels, default),
                             'static_reached_helpers_not_runtime_branch_count': sorted(reached), 'sites': sites,
                             'assertion_scope': 'Whole unchanged Original workflow including its original mocks; no router/TCP/credential/worker/whole-endpoint guarantee'}
    for identifier, identity in IDENTITIES.items():
        route, operation = index[identifier]
        assert {key: route[key] for key in ['pattern_exact', 'source_handler']} == {key: identity[key] for key in ['pattern_exact', 'source_handler']}
        assert all(operation[key] == identity[key] for key in ['method', 'source_action', 'owning_milestone'])
        assert operation['fully_verified'] is False
    return {'fixtures': fixtures, 'cases': cases}


def dependencies():
    return [PREFIX + 'bindings.json'] + [reference['path'] for reference in ORIGINAL_FILES + AUTHORITIES]


def generate(root, registry):
    root = Path(root)
    summary = json.loads((root / 'scripts/rust-contracts/framework-auth/full-suite-reference.json').read_text())
    assert summary['tests_passed'] == 3362 and summary['exit_code'] == 0
    derived = derive(root, registry)
    observation = json.loads((root / (PREFIX + 'observations.json')).read_text())
    assert set(observation['cases']) == set(derived['cases'])
    for identifier, case in derived['cases'].items():
        record = observation['cases'][identifier]
        assert record['historical_result'] == 'ok' and record['framework_log_block'].startswith(case['method'] + ' (' + identifier + ')')
        assert re.search(r'(?:\.\.\. |\n)ok\s*\Z', record['framework_log_block'])
        assert digest(record['framework_log_block'].encode()) == record['framework_log_block_sha256']
        assert record['full_log_byte_end'] - record['full_log_byte_start'] == len(record['framework_log_block'].encode())
        case.update(record)
        case['replay_kind'] = 'retained_historical_named_Original_workflow_offline_definition_replay'
    fixtures, contracts = {}, []
    for identifier, identity in IDENTITIES.items():
        selected = [derived['cases'][name] for name in EXPECTED_TESTS[identifier]]
        scope = dispatch_scope(identity['pattern_exact'])
        fixture_id = 'proxy-plugin:' + identifier
        fixtures[fixture_id] = {
            'id': fixture_id, 'baseline_revision': ORIGINAL, 'baseline_image': summary['image'],
            'execution': {'entrypoint': 'scripts/rust-baseline/run.py',
                          'argv': ['--output', '<fresh-empty-owned-output>', *[case['test_id'] for case in selected]],
                          'fresh_live_replay_qualified_this_task': False},
            'class_fixture_definitions': {key: derived['fixtures'][key] for key in sorted({case['fixture_id'] for case in selected})},
            'ownership': 'Unchanged Original disposable TestCase/TransactionTestCase data and exact temporary fixture/mocks; no production service',
            'transport_scope': scope['transport'], 'credential_backend_complete': False,
        }
        sites = [site for case in selected for site in case['sites'] if site['contract_id'] == identifier]
        contracts.append(dict(identity, contract_id=identifier, fixture_id=fixture_id,
            observed_request_methods=sorted({site['observed_method'] for site in sites}),
            observed_roles=[scope['role_label']],
            source_role_specs={scope['role_label']: {'authority': 'Exact per-case typed fixture declarations/auth/permission expressions below',
                'case_role_contexts': {case['test_id']: case['role_context'] for case in selected}, 'complete_role_matrix': False}},
            cases=selected, assertions=ASSERTIONS,
            result={'state': 'historical_Original_proxy_plugin_definitions_passed_not_new_execution',
                    'historical_named_cases': len(selected), 'new_Source_cases_this_task': 0,
                    'historical_authority': 'scripts/rust-baseline/verified-full-baseline.json'},
            fully_verified=False,
            remaining=['Original factory/forced/synthetic actors, permission bypasses, auth/service/Redis/installer mocks retain only their original scope',
                       'Static helper/literal dispatch definitions do not prove branch hit counts, real credentials, TCP, workers or whole endpoint behavior',
                       'Unobserved roles/grammar/aliases, Native/browser/resources/performance and formal M0/M1 remain open']))
    return {'format_version': 1, 'binding_kind': KIND, 'Original_revision': ORIGINAL,
            'original_test_files': ORIGINAL_FILES, 'authorities': AUTHORITIES,
            'operation_count': len(contracts), 'unique_historical_test_cases': len(derived['cases']),
            'static_source_helper_sites': sum(len(case['sites']) for case in derived['cases'].values()),
            'new_Source_cases_this_task': 0, 'fixtures': fixtures, 'contracts': contracts,
            'non_HTTP_contracts': [], 'Native_coverage_increased': False, 'fully_verified_added': 0}


def validate(root, value, bindings=None):
    root = Path(root)
    registry = json.loads((root / 'docs/rust-contract-register.json').read_text())
    assert value == generate(root, registry), 'exact proxy/plugin Source fixture/endpoint/helper/actor/assertion/result definitions'
    return {'passed': True, 'operations': len(IDENTITIES), 'historical_named_cases': len(TEST_COORDINATES),
            'new_Source_executions': 0, 'fully_verified_added': 0}


def main():
    import argparse
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--root', type=Path, default=Path(__file__).resolve().parents[2])
    parser.add_argument('--historical-log', type=Path)
    parser.add_argument('--write-bindings', action='store_true')
    args = parser.parse_args()
    registry = json.loads((args.root / 'docs/rust-contract-register.json').read_text())
    value = generate(args.root, registry)
    if args.write_bindings:
        (args.root / (PREFIX + 'bindings.json')).write_text(json.dumps(value, indent=2) + '\n')
    else:
        validate(args.root, json.loads((args.root / (PREFIX + 'bindings.json')).read_text()))
    result = {'passed': True, 'operations': len(value['contracts']), 'cases': value['unique_historical_test_cases'],
              'static_sites_not_runtime_count': value['static_source_helper_sites'], 'new_Source_executions': 0}
    if args.historical_log is not None:
        raw = args.historical_log.read_bytes()
        observation = json.loads((args.root / (PREFIX + 'observations.json')).read_text())
        assert digest(raw) == observation['full_log_sha256'] and len(raw) == observation['full_log_bytes']
        for record in observation['cases'].values():
            assert raw[record['full_log_byte_start']:record['full_log_byte_end']] == record['framework_log_block'].encode()
        result['deep_historical_raw_blocks'] = len(observation['cases'])
    print(json.dumps(result))


if __name__ == '__main__':
    main()
